START='2026-09-30T10:00:00Z'
END='2026-09-30T11:00:00Z'
def row(id,ts,latency=1,status=200):return dict(id=id,ts=ts,latency_ms=latency,status=status)
class Holdout(unittest.TestCase):
    def test_timezone_bounds(self):
        xs=[row('start','2026-09-30T05:00:00-05:00'),row('end','2026-09-30T13:00:00+02:00')]
        self.assertEqual(summarize(xs,START,END),dict(count=1,errors=0,p95_ms=1))
    def test_unordered_retries(self):
        xs=[row('x','2026-09-30T10:30:00Z',7),row('x','2026-09-30T10:01:00Z',99,500)]
        self.assertEqual(summarize(xs,START,END),dict(count=1,errors=0,p95_ms=7))
    def test_tie_last_input(self):
        xs=[row('x','2026-09-30T10:30:00Z',7),row('x','2026-09-30T12:30:00+02:00',11,503)]
        self.assertEqual(summarize(xs,START,END),dict(count=1,errors=1,p95_ms=11))
    def test_outside_retry_does_not_erase(self):
        xs=[row('x','2026-09-30T10:30:00Z',7),row('x','2026-09-30T11:30:00Z',99,500)]
        self.assertEqual(summarize(xs,START,END),dict(count=1,errors=0,p95_ms=7))
    def test_immutability(self):
        xs=[row('b','2026-09-30T10:30:00Z',7),row('a','2026-09-30T10:01:00Z',99,500)];before=copy.deepcopy(xs)
        summarize(xs,START,END);self.assertEqual(xs,before)
    def test_rank_boundaries(self):
        for n in [1,2,19,20,21,99,100,101]:
            with self.subTest(n=n):
                xs=[row(str(i),'2026-09-30T10:30:00Z',i/2) for i in range(1,n+1)]
                self.assertEqual(summarize(xs,START,END)['p95_ms'],math.ceil(n*.95)/2)
    def test_invalid_record_types(self):
        good=row('x','2026-09-30T10:30:00Z',7)
        invalid=[None,[],{},dict(good,id=''),dict(good,status=True),dict(good,status='200'),dict(good,status=600),dict(good,latency_ms=True),dict(good,latency_ms=-1),dict(good,latency_ms=float('nan')),dict(good,latency_ms=float('inf')),dict(good,ts='2026-09-30T10:30:00')]
        data='\n'.join([json.dumps(good),*[json.dumps(x) for x in invalid],'\n','bad-json'])
        p=subprocess.run([sys.executable,'report.py','--input','-','--start',START,'--end',END],input=data,cwd=ROOT,capture_output=True,text=True)
        self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(json.loads(p.stdout),dict(count=1,errors=0,p95_ms=7,invalid_lines=len(invalid)+1))
    def test_generated_reference(self):
        rng=random.Random(20260930);utc=datetime.timezone.utc;base=datetime.datetime(2026,9,30,10,tzinfo=utc)
        for case in range(100):
            xs=[];observations=[]
