                x=row(str(rng.randrange(12)),instant.astimezone(datetime.timezone(datetime.timedelta(hours=offset))).isoformat(),rng.randrange(1000),rng.choice([200,404,500,503]));xs.append(x)
                if 0<=minute<60:observations.append((minute,i,x))
            chosen=[]
            for identity in {x[2]['id'] for x in observations}:
