import argparse
import gzip
import json
import math
import sys
from datetime import datetime, timezone


def _parse_timestamp(value):
    if not isinstance(value, str):
        return None
    if value.endswith('Z'):
        value = value[:-1] + '+00:00'
    try:
        parsed = datetime.fromisoformat(value)
    except ValueError:
        return None
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        return None
    return parsed.astimezone(timezone.utc)


def _valid_event(event):
    if not isinstance(event, dict):
        return False
    event_id = event.get('id')
    status = event.get('status')
    latency = event.get('latency_ms')
    if not isinstance(event_id, str) or not event_id:
        return False
    if isinstance(status, bool) or not isinstance(status, int) or not 100 <= status <= 599:
        return False
    if isinstance(latency, bool) or not isinstance(latency, (int, float)):
        return False
    if isinstance(latency, float) and not math.isfinite(latency):
        return False
    if latency < 0:
        return False
    return _parse_timestamp(event.get('ts')) is not None


def summarize(events, start, end):
    start_time = _parse_timestamp(start)
    end_time = _parse_timestamp(end)
    if start_time is None or end_time is None:
        raise ValueError('start and end must be timezone-aware ISO-8601 timestamps')

    selected = {}
    for event in events:
        if not _valid_event(event):
            continue
        event_time = _parse_timestamp(event['ts'])
        if start_time <= event_time < end_time:
            previous = selected.get(event['id'])
            if previous is None or event_time >= previous[0]:
                selected[event['id']] = (event_time, event)

    values = [event for _, event in selected.values()]
    latencies = sorted(event['latency_ms'] for event in values)
    count = len(latencies)
    p95_ms = latencies[(95 * count + 99) // 100 - 1] if count else 0
    return {
        'count': count,
        'errors': sum(event['status'] >= 500 for event in values),
        'p95_ms': p95_ms,
    }


def _read_events(path):
    if path == '-':
        source = sys.stdin.buffer
        close_source = False
    elif path.endswith('.gz'):
        source = gzip.open(path, 'rb')
        close_source = True
    else:
        source = open(path, 'rb')
        close_source = True

    events = []
    invalid_lines = 0
    try:
        for raw_line in source:
            if not raw_line.strip():
                continue
            try:
                line = raw_line.decode('utf-8')
            except UnicodeDecodeError:
                invalid_lines += 1
                continue
            try:
                event = json.loads(line)
            except (ValueError, RecursionError):
                invalid_lines += 1
                continue
            if not _valid_event(event):
                invalid_lines += 1
                continue
            events.append(event)
    finally:
        if close_source:
            source.close()
    return events, invalid_lines


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--input', required=True)
    parser.add_argument('--start', required=True)
    parser.add_argument('--end', required=True)
    args = parser.parse_args()

    events, invalid_lines = _read_events(args.input)
    result = summarize(events, args.start, args.end)
    result['invalid_lines'] = invalid_lines
    print(json.dumps(result, sort_keys=True))


if __name__ == '__main__':
    main()
PY

