import json
import subprocess
import sys
import unittest

from report import summarize

START = '2026-09-30T10:00:00Z'
END = '2026-09-30T11:00:00Z'


def event(id='a', ts='2026-09-30T10:15:00Z', status=200, latency=10):
    return {'id': id, 'ts': ts, 'status': status, 'latency_ms': latency}


class RegressionTests(unittest.TestCase):
    def test_offset_timestamps_are_compared_as_instants(self):
        rows = [event(ts='2026-09-30T12:15:00+02:00')]
        self.assertEqual(summarize(rows, START, END), {
            'count': 1, 'errors': 0, 'p95_ms': 10,
        })

    def test_latest_in_window_event_wins_and_out_of_window_event_is_ignored(self):
        rows = [
            event(status=503, latency=90),
            event(ts='2026-09-30T10:20:00Z', latency=20),
            event(ts=END, status=500, latency=1000),
        ]
        self.assertEqual(summarize(rows, START, END), {
            'count': 1, 'errors': 0, 'p95_ms': 20,
        })

    def test_last_occurrence_wins_for_equal_timestamps(self):
        rows = [
            event(ts='2026-09-30T10:20:00Z', status=503, latency=90),
            event(ts='2026-09-30T10:20:00Z', latency=12),
        ]
        self.assertEqual(summarize(rows, START, END), {
            'count': 1, 'errors': 0, 'p95_ms': 12,
        })

    def test_summary_does_not_mutate_events(self):
        row = event()
        original = dict(row)
        summarize([row], START, END)
        self.assertEqual(row, original)

    def test_cli_counts_bad_json_records_and_invalid_utf8_lines(self):
        valid = json.dumps(event()).encode('utf-8')
        malformed = b'{broken'
        incomplete = json.dumps({'id': 'missing-fields'}).encode('utf-8')
        boolean_status = json.dumps(event(id='bool', status=True)).encode('utf-8')
        infinite_latency = json.dumps(event(id='infinite', latency=float('inf'))).encode('utf-8')
        content = b'\n'.join([
            valid, malformed, incomplete, boolean_status, infinite_latency,
            b'\xff', b'',
        ])
        run = subprocess.run([
            sys.executable, 'report.py', '--input', '-',
            '--start', START, '--end', END,
        ], input=content, capture_output=True)
        self.assertEqual(run.returncode, 0, run.stderr.decode('utf-8', errors='replace'))
        self.assertEqual(json.loads(run.stdout), {
            'count': 1, 'errors': 0, 'p95_ms': 10, 'invalid_lines': 5,
        })


if __name__ == '__main__':
    unittest.main()
